void Page_Load(object sender, EventArgs e)
        {
            int patient_id = 0;
            if (Request.QueryString["patient_row_id"] != null)
            {
                int.TryParse(Request.QueryString["patient_row_id"].ToString(), out patient_id);
            }
            if (patient_id > 0)
            {
                Patient objpatient = new Patient();
                objpatient = Patient.Get(patient_id);
                if (objpatient != null)
                {
                    Session["Patient_Communication"] = patient_id.ToString();
                    lblKmedId.Text = objpatient.KmedID;
                    lblPatientName.Text = objpatient.FirstName + " " + objpatient.LastName;
                    string age = "";
                    string gender = "";
                    if (objpatient.age != null)
                    {
                        age = Convert.ToString(objpatient.age);
                    }
                    else if (objpatient.dob != null)
                    {
                        age = (System.DateTime.Now.Year - ((DateTime)objpatient.dob).Year).ToString();
                    }
                    else
                    {
                        age = "_";
                    }
                    if (objpatient.gender != null)
                        gender = objpatient.gender.ToString();
                    else
                        gender = "_";

                    lblAgenGender.Text = age + "/" + gender;
                }
            }
        }

